sizes, err := getArchiveSizes(input)
if err != nil {
	return err
}

header = append(header, "CHKPT Size")
row = append(row, metadata.ByteToString(sizes.checkpointSize))

// Display root fs diff size if available
if sizes.rootFsDiffTarSize != 0 {
	header = append(header, "Root Fs Diff Size")
	row = append(row, metadata.ByteToString(sizes.rootFsDiffTarSize))
}

// archiveSizes represents the size of different parts of a checkpoint archive.
type archiveSizes struct {
	// checkpointSize is the size of the checkpoint directory.
	checkpointSize int64
	// rootFsDiffTarSize is the size of the rootfs-diff.tar file.
	rootFsDiffTarSize int64
}

// getArchiveSizes calculates the sizes of the checkpoint directory and the
// rootfs-diff.tar file from an archive file without unpacking the files.
func getArchiveSizes(input string) (*archiveSizes, error) {
	result := &archiveSizes{}

	archiveFile, err := os.Open(input)
	if err != nil {
		return nil, err
	}
	defer archiveFile.Close()

	// Decompress the archive
	decompressedStream, err := archive.DecompressStream(archiveFile)
	if err != nil {
		return nil, err
	}
	defer decompressedStream.Close()

	// Create a tar reader to read the files from the decompressed archive
	tarReader := tar.NewReader(decompressedStream)

	// Iterate through each file in the archive
	for {
		hdr, err := tarReader.Next()
		if err == io.EOF {
			// End of archive
			break
		}
		if err != nil {
			return nil, err
		}

		// Check if it's a regular file
		if !hdr.FileInfo().IsDir() && strings.HasPrefix(hdr.Name, metadata.CheckpointDirectory) {
			// Add the file size to the total checkpoint size
			result.checkpointSize += hdr.Size
		}

		if hdr.Name == metadata.RootFsDiffTar {
			result.rootFsDiffTarSize = hdr.Size
		}
	}

	return result, nil
}
